export const BRAND_MARKS = Object.freeze({
  ...Object.fromEntries(Object.entries(MARKS).map(([k, v]) => [k, Object.freeze({
    ...v, source: SI(v.slug), version: SIMPLE_ICONS.version, licence: SIMPLE_ICONS.licence,
  })])),
  ...VENDOR_MARKS,
});

/** Keys that are not brands: a lucide glyph. */
export const BRAND_GENERIC = Object.freeze({
  phone_speaker: Object.freeze({ name: 'Phone', Icon: Phone }),
  sms: Object.freeze({ name: 'SMS', Icon: MessageSquare }),
  paste: Object.freeze({ name: 'Paste', Icon: ClipboardPaste }),
  other: Object.freeze({ name: 'Another client', Icon: Bot }),
  website: Object.freeze({ name: 'Website', Icon: Globe }),
  email: Object.freeze({ name: 'Email', Icon: Mail }),
});

const MS_TERMS = 'Microsoft\'s Trademark and Brand Guidelines (https://www.microsoft.com/en-us/legal/intellectualproperty/trademarks/usage/general, read 2026-10-14): "our logos, app and product icons, illustrations, photographs, videos, and designs can never be used without an express license". Axal has none, so initials.';

/** Initials on purpose, each with why. */
export const BRAND_MONOGRAM = Object.freeze({
  teams: Object.freeze({ name: 'Microsoft Teams', reason: MS_TERMS }),
  carta: Object.freeze({ name: 'Carta', reason: 'The official press page (https://carta.com/press/, read 2026-10-16) links a Google Drive press kit, but its asset files could not be retrieved here. Third-party Carta SVGs were found, but their match to the current vendor kit has not been verified. Initials until the vendor asset is recorded.' }),
  affinity: Object.freeze({ name: 'Affinity', reason: 'Affinity CRM is affinity.co, not the Affinity design suite. The vendor newsroom (https://www.affinity.co/company/newsroom, read 2026-10-16) has no downloadable icon kit. Brandfetch and an n8n SVG were located, but their current vendor provenance and permitted treatment remain unverified. Initials until that is recorded.' }),
});

/** A second key for the same brand (REGISTRY_ALIAS's two, the profile's `twitter`, the admin `gcip`). */
export const BRAND_ALIAS = Object.freeze({
  google_calendar: 'google',
  microsoft_365: 'microsoft',
  twitter: 'x',
  gcip: 'google',
});

/**
 * What a key draws: `{ kind: 'mark' | 'generic' | 'monogram' | 'unknown', key }`.
 * Own keys only (`Object.hasOwn`), so `constructor` or `__proto__` never
 * resolves to anything but the monogram.
 */
export function resolveBrand(key) {
  const raw = typeof key === 'string' ? key.trim().toLowerCase() : '';
  const k = Object.hasOwn(BRAND_ALIAS, raw) ? BRAND_ALIAS[raw] : raw;
  if (Object.hasOwn(BRAND_MARKS, k)) return { kind: 'mark', key: k, mark: BRAND_MARKS[k] };
  if (Object.hasOwn(BRAND_GENERIC, k)) return { kind: 'generic', key: k, generic: BRAND_GENERIC[k] };
  if (Object.hasOwn(BRAND_MONOGRAM, k)) return { kind: 'monogram', key: k, monogram: BRAND_MONOGRAM[k] };
  return { kind: 'unknown', key: null };
}

/** Initials from a name, as the Connectors page always drew them. */
export function initials(name) {
  return String(name || '?').split(/\s+/).filter(Boolean).map((w) => w[0]).join('').slice(0, 2).toUpperCase() || '?';
}

// The canvas tile (Connectors Page.dc.html:74): 34px with an 18px mark, 24px with a 14px one.
const GLYPH = { 34: 18, 24: 14 };
const glyphFor = (size) => GLYPH[size] || Math.round(size * 0.53);
export const TILE_CLASS = 'grid shrink-0 place-items-center rounded-[9px] border border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800';
export const MULTI_TILE_CLASS = 'grid shrink-0 place-items-center rounded-[9px] border border-gray-200 bg-white dark:border-gray-700 dark:bg-white';
export const MONOGRAM_CLASS = 'grid shrink-0 place-items-center rounded-[9px] bg-axal-lavender text-[11px] font-bold text-axal-violet-deep dark:bg-violet-900/30 dark:text-violet-300';
export const BRAND_COLOUR_CLASS = 'text-[color:var(--brand)] dark:text-[color:var(--brand-dark)]';

function scopedArtworkProps(attrs, prefix) {
  return Object.fromEntries(Object.entries(attrs).map(([key, value]) => {
    if (key === 'id') return [key, `${prefix}-${value}`];
    if (key === 'href' && value.startsWith('#')) return [key, `#${prefix}-${value.slice(1)}`];
    if (typeof value === 'string') {
      return [key, value.replace(/url\(#([^)]+)\)/g, (_, id) => `url(#${prefix}-${id})`)];
    }
    return [key, value];
  }));
}

function renderArtwork(node, prefix, key) {
  return React.createElement(node.tag, { ...scopedArtworkProps(node.attrs, prefix), key },
    ...node.children.map((child, i) => renderArtwork(child, prefix, i)));
}

function Svg({ mark, k, px, brand, className = '' }) {
  // React useId keeps repeated Google gradients independent and hydration-stable.
  const prefix = useId().replace(/[^A-Za-z0-9_-]/g, '');
  const multicolour = !!(mark.multicolour || mark.paths);
  const style = brand && !multicolour ? { '--brand': mark.hex, '--brand-dark': mark.dark } : undefined;
  return (
    <svg {...mark.rootProps} viewBox={mark.viewBox || '0 0 24 24'} width={px} height={px} aria-hidden="true" focusable="false" data-provider={k}
      fill="currentColor" style={style} className={`shrink-0 ${brand && !multicolour ? BRAND_COLOUR_CLASS : ''} ${className}`.trim()}>
      {mark.artwork
        ? mark.artwork.map((node, i) => renderArtwork(node, prefix, i))
        : mark.paths ? mark.paths.map((p) => <path key={p.d} d={p.d} fill={p.fill} />) : <path d={mark.path} />}
    </svg>
  );
}

/**
 * A service's mark, next to its visible name; never the only label.
 *   provider  the key (`p.key`)
 *   name      the visible name, for the monogram
 *   size      34 or 24 for a tile; for `bare`, the glyph's own pixel size
 *   variant   'tile' | 'bare'
 *   tone      'brand' (its own colour) | 'current' (currentColor, no tile)
 *   fallback  'monogram' | 'none' (draw only a real mark)
 */
export default function BrandIcon({ provider, name = '', size = 34, variant = 'tile', tone = 'brand', fallback = 'monogram', className = '' }) {
  const r = resolveBrand(provider);
  if (fallback === 'none' && r.kind !== 'mark') return null;
  const bare = variant === 'bare' || tone === 'current';
  const px = bare ? size : glyphFor(size);
  if (r.kind === 'mark') {
    const svg = <Svg mark={r.mark} k={r.key} px={px} brand={tone !== 'current'} className={bare ? className : ''} />;
    if (bare) {
      // A multi-colour mark keeps a white backing in dark mode, as the sign-in button does.
      return (r.mark.multicolour || r.mark.paths) ? <span className="inline-grid shrink-0 place-items-center rounded-[4px] dark:bg-white">{svg}</span> : svg;
    }
    return <span aria-hidden="true" style={{ width: size, height: size }} className={`${r.mark.multicolour || r.mark.paths ? MULTI_TILE_CLASS : TILE_CLASS} ${className}`.trim()} data-brand="mark">{svg}</span>;
  }
  if (r.kind === 'generic') {
    const { Icon } = r.generic;
    const glyph = <Icon size={px} aria-hidden="true" focusable="false" data-provider={r.key} className={bare ? `shrink-0 ${className}`.trim() : 'text-gray-600 dark:text-gray-300'} />;
    if (bare) return glyph;
    return <span aria-hidden="true" style={{ width: size, height: size }} className={`${TILE_CLASS} ${className}`.trim()} data-brand="generic">{glyph}</span>;
  }
  // The monogram: the Connectors page's initials tile, unchanged (AccountConnectors.jsx, D651).
  const label = name || r.monogram?.name || '';
  return (
    <span aria-hidden="true" style={{ width: size, height: size }} className={`${MONOGRAM_CLASS} ${className}`.trim()}
      data-brand="monogram" data-provider={r.key || undefined}>
      {initials(label)}
    </span>
  );
}

export { BrandIcon };

